import{_ as a,o,c as i,ag as s}from"./chunks/framework.BwSLX4ak.js";const b=JSON.parse('{"title":"BiliMusicBridge troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/bilimusicbridge/troubleshooting.md","filePath":"en/bilimusicbridge/troubleshooting.md"}'),r={name:"en/bilimusicbridge/troubleshooting.md"};function t(l,e,n,c,u,d){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="bilimusicbridge-troubleshooting" tabindex="-1">BiliMusicBridge troubleshooting <a class="header-anchor" href="#bilimusicbridge-troubleshooting" aria-label="Permalink to &quot;BiliMusicBridge troubleshooting&quot;">​</a></h1><h2 id="allmusic-is-unavailable" tabindex="-1">AllMusic is unavailable <a class="header-anchor" href="#allmusic-is-unavailable" aria-label="Permalink to &quot;AllMusic is unavailable&quot;">​</a></h2><p>Use AllMusic 4.2.0 or newer in the same instance as BiliMusicBridge. The proxy bridge cannot call AllMusic on a separate Bukkit backend. Check source loading in AllMusic&#39;s logs and ensure <code>defaultApi</code> matches the source ID.</p><h2 id="chat-arrives-but-no-song-is-requested" tabindex="-1">Chat arrives but no song is requested <a class="header-anchor" href="#chat-arrives-but-no-song-is-requested" aria-label="Permalink to &quot;Chat arrives but no song is requested&quot;">​</a></h2><p>Check <code>room-id</code>, <code>song-request.prefixes</code>, and <code>/bilimusic status</code>. The default prefix is <code>点歌</code>, and messages must start with it. Empty keywords or text exceeding <code>max-keyword-length</code> do not enter the normal request flow.</p><p>Defaults are a 20-second cooldown per Bilibili account, a 1000 ms global interval, an 8-second duplicate-keyword window, and a pending queue capacity of 100. Run <code>/bilimusic reload</code> after changing these values. If failures are not broadcast to players, inspect console logs or enable <code>messages.broadcast-failure</code> as needed.</p><h2 id="no-players-duplicate-song-or-full-queue" tabindex="-1">No players, duplicate song, or full queue <a class="header-anchor" href="#no-players-duplicate-song-or-full-queue" aria-label="Permalink to &quot;No players, duplicate song, or full queue&quot;">​</a></h2><p>The default <code>allmusic.require-online-player: true</code> requires an online player eligible for playback. The bridge retains AllMusic&#39;s queue length, duplicates, song blacklist, per-player limits, and other checks. Livestream viewers are not Minecraft accounts, so direct enqueueing does not charge Vault or proxy economy balances.</p><h2 id="where-cookies-go" tabindex="-1">Where cookies go <a class="header-anchor" href="#where-cookies-go" aria-label="Permalink to &quot;Where cookies go&quot;">​</a></h2><p>Cookies are optional. Put them in the current BiliMusicBridge data directory, normally as <code>cookie.json</code>. Browser-exported arrays, JSON objects, and raw Cookie headers are supported. The path must stay inside the data directory. Cookies and generated <code>device.properties</code> are runtime data and should not be included in public documentation.</p><h2 id="a-song-is-found-but-players-hear-nothing" tabindex="-1">A song is found but players hear nothing <a class="header-anchor" href="#a-song-is-found-but-players-hear-nothing" aria-label="Permalink to &quot;A song is found but players hear nothing&quot;">​</a></h2><p>Check that AllMusic client/server versions match and the source returns a usable playback URL. BiliMusicBridge receives chat, searches, and enqueues; AllMusic and the source still handle actual resolution and playback. See <a href="./../allmusic/troubleshooting.html">Music source troubleshooting</a>.</p>',12)])])}const g=a(r,[["render",t]]);export{b as __pageData,g as default};
